// the missing prefixes. Total work and storage are linear, including const
// evaluation, which cannot reuse an array updated repeatedly in a loop.
const prefix_sums = fn (values: Array U32) -> Array U32 => do:
  if values.length < 2:
    break values
  let pairs = generate (values.length / 2) (fn index =>
    values[index * 2] + values[index * 2 + 1])
  let ends = prefix_sums pairs
  break generate values.length (fn index =>
    if index % 2 == 1 then ends[index / 2]
    else if index == 0 then values[0]
